"""Nov 12, 2026 re-pricing of the 2026-27 Topps Flagship Basketball deep review from eBay sold listings
(LH_Sold=1&LH_Complete=1) read in the browser pane on Nov 12 (sales Nov 5 to 12, a week after the Nov 5 release).
Idempotent: each edit asserts the old text and is skipped when already applied. Counts, ranges and date windows are
stated per line; break slots, lots, cases, hot packs, complete sets and 'you pick' listings excluded by title; box
medians floor at a sanity price to drop mis-tagged singles. PSA was not readable (sign-in wall), so no graded prices."""
import json, os, re
P = os.path.join(os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__)))), 'src/index.src.html')
s = open(P).read()

def load(slug):
    m = re.search(r'^( /\* ' + re.escape(slug) + r' \*/)(\{.*\})(,?)$', s, re.M)
    assert m, slug
    return m, json.loads(m.group(2))

def save(m, obj):
    global s
    line = m.group(1) + json.dumps(obj, ensure_ascii=False, separators=(',', ':')) + m.group(3)
    s = s[:m.start()] + line + s[m.end():]

def rep(obj, path, old, new):
    cur = obj
    for k in path[:-1]: cur = cur[k]
    v = cur[path[-1]]
    if new in v and old not in v: return  # already applied
    assert old in v, (path, old[:60])
    cur[path[-1]] = v.replace(old, new)

m, r = load('topps-flagship-bk-2026-27')
